import{connectedTerrain,paintSampler}from'./terrain.js';
// Source silhouettes/animation own geometry. Painted atlas cells provide color.
// Join integer world chunks before filtering, as in the established cave path.
export class PaintedTerrain{
 constructor(){this.cache=new Map();}
 draw(hd,a,l,map,cx,cy,animation){const size=64,halo=16,extent=96,cols=6,bankOf=v=>v<256?a.tiles[l.id]:a.union,value=(x,y)=>x<0||x>=4096||y<0||y>=l.height*16?256:l.lookup[animation.remap[map[(y>>4)*256+(x>>4)]]];const keys=new Set();hd.connectedLayer(cx,cy,(c,b)=>{for(let gy=b.y0;gy<=b.y1;gy++)for(let gx=b.x0;gx<=b.x1;gx++){const ox=gx*size,oy=gy*size,values=[];for(let y=0;y<cols;y++)for(let x=0;x<cols;x++)values.push(value(ox-halo+x*16,oy-halo+y*16));const key=l.id+':'+gx+':'+gy+':'+animation.phase,signature=values.join(',');keys.add(key);let chunk=this.cache.get(key);if(!chunk||chunk.signature!==signature){const source=new Uint8Array(extent*extent),textures=values.map(v=>{if(v===256||v===65535||v===undefined)return null;const record=hd.pack.manifest.tiles?.[l.id+':'+(v<256?'local:':'union:')+(v<256?v:v-256)];return record?.atlas.startsWith('v16-')?hd.terrainTexture(record):null;});for(let y=0;y<extent;y++)for(let x=0;x<extent;x++){const wx=ox+x-halo,wy=oy+y-halo,v=values[(y>>4)*cols+(x>>4)];if(v!==256&&v!==65535&&v!==undefined)source[y*extent+x]=bankOf(v)?.[(v<256?v:v-256)*256+(wy&15)*16+(wx&15)]||0;}const paint=paintSampler(textures,cols),rgba=connectedTerrain(source,extent,extent,hd.palette,paint,{paintColor:true}),image=document.createElement('canvas');image.width=image.height=256;image.getContext('2d').putImageData(new ImageData(rgba,384,384),-64,-64);chunk={signature,image};this.cache.set(key,chunk);}c.drawImage(chunk.image,ox*4,oy*4);}});for(const key of this.cache.keys())if(this.cache.size>96&&!keys.has(key))this.cache.delete(key);return true;}
}
